"""Validate budgets/source preservation and generate decision and shop-order reports."""
import csv,gzip,hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
R=ROOT/'cm21-study/research'
cat={r['id']:r for r in json.loads((R/'skill_catalog.json').read_text())}
packages=json.loads((R/'packages.json').read_text())
rows=list(csv.DictReader(open(R/'package_comparison.csv')))
lookup={(r['scenario'],r['package']):r for r in rows}
v=json.loads((R/'verification.json').read_text())
up=list(csv.DictReader(open(R/'upgrade_ablation.csv')))
raw=json.loads(gzip.decompress((R/'raw_results.json.gz').read_bytes()))
activation_rows=[]
for key,r in raw['packages'].items():
    scenario,name=key.split(':')
    for id in ['100411',*packages[name]]:
        events=[e for es in r['events'] for e in es if e['id']==id]
        activation_rows.append({'scenario':scenario,'package':name,'id':id,'skill':cat[id]['name'] if id in cat else 'Native unique Lv4','trials':len(r['events']),'activation_rate':sum(any(e['id']==id for e in es) for es in r['events'])/len(r['events']),'mean_activation_m':sum(e['pos'] for e in events)/len(events) if events else '', 'mean_activation_s':sum(e['t'] for e in events)/len(events) if events else ''})
with open(R/'package_activation.csv','w') as f:
    w=csv.DictWriter(f,fieldnames=activation_rows[0]);w.writeheader();w.writerows(activation_rows)
for name,ids in packages.items():
    assert sum(cat[i]['total_player_cost'] for i in ids)<=2751
    assert len(set(cat[i]['meta']['groupId'] for i in ids))==len(ids)
assert v['replay_exact']
changed=subprocess.check_output(['git','diff','96b870a','--name-only','--','uma-skill-tools','umalator','umalator-global','components'],cwd=ROOT,text=True)
assert not changed,changed
inputs=['CM21_RESEARCH_TASK.md','CM21_Codex_Handoff_REMADE.zip','uma-skill-tools/RaceSolver.ts','uma-skill-tools/RaceSolverBuilder.ts','uma-skill-tools/ActivationConditions.ts','uma-skill-tools/ActivationSamplePolicy.ts','uma-skill-tools/HpPolicy.ts','umalator/compare.ts','umalator-global/skill_data.json','umalator-global/course_data.json','umalator-global/skill_meta.json','cm21-study/cm21_nine_runner_pseudo_sim.py']
(R/'source_hashes.json').write_text(json.dumps({p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in inputs},indent=2))
# Budget is a cap: leave points unspent when additional value is unsubstantiated.
selected=[('conservative','1. Lower dependence on nearby runners'),('candidate_1','2. Conditional proximity package'),('prior_balanced','3. Prior balanced package, retained as a hedge')]
white_for={'200331':'200332','200651':'200652','200981':'200982','201271':'201272','201662':'201661','210071':'210072','200131':'200132','200151':'200152','200201':'200202','200261':'200262','201241':'201242','201521':'201522'}
lines=['# Recommended shop order and alternatives','','**Research recommendation: use the lower-proximity-dependence package as the default for review; prefer the conditional package only with practice-room evidence for its positional skills. Do not purchase until current-client conditions, available hints, and shop totals are checked. No points were spent.**','','These are the most useful measured alternatives, not a proven exhaustive optimum. Costs below use the supplied final totals. Gold totals include the white prerequisite; ◎ totals include ○. Where the shop shows an incremental upgrade, buy the white/○ first and then only the difference shown here. The total is verified arithmetically, but hint discounts were not independently observed. Native unique Lv4 stays equipped for zero additional SP.','']
for name,title in selected:
    ids=packages[name]
    ordered=sorted(ids,key=lambda i: (0 if i in ['200202','200201','200152','200151','201522','201521'] else 1 if i=='201601' else 2 if i=='200532' else 3 if i=='900141' else 4,ids.index(i)))
    cost=sum(cat[i]['total_player_cost'] for i in ids)
    lines += ['## '+title,'',f'Engine package key `{name}`; **{cost} SP; {2751-cost} SP remaining**.','','| Order | Purchase | SP from unowned | Cumulative |','|---:|---|---:|---:|']
    cumul=0
    for j,i in enumerate(ordered,1):
        item=cat[i];p=item['total_player_cost'];w=white_for.get(i)
        label=item['name']
        if w:label+=f" ({cat[w]['name']} {cat[w]['total_player_cost']} → upgrade +{p-cat[w]['total_player_cost']})"
        cumul+=p;lines.append(f'| {j} | {label} | {p} | {cumul} |')
    lines+=['', '| Assumption | Seconds saved vs same-scenario baseline |','|---|---:|']
    for scenario in ['sampled','no-proximity','rank-2','back-rank']:
        r=lookup[(scenario,name)];lines.append(f"| {scenario} | {float(r['seconds_saved']):.3f} ({float(r['ci95_low']):.3f} to {float(r['ci95_high']):.3f}) |")
    if name=='conservative':lines+=['','Avoids purchasing Cacao, Top Runner, See Ya Later and Staggering/Huge Lead, whose proximity/gap checks are sampled in this engine. Mad Dash costs 4% HP; check debuff/competition scenarios in practice before accepting that tradeoff. Victoria still needs top-two position and HP; native unique still needs side contact. Tail Held High depends on actual middle activations. “Lower dependence” does not mean unconditional.']
    elif name=='candidate_1':lines+=['','Best-value conditional shortlist choice: the alternative candidate_2 is nearly tied and costs more; no meaningful superiority is established between them. This package requires both a lead gap (Staggering Lead) and opponent interaction (Top Runner/See Ya Later/Cacao) at useful times. The engine samples these separately and cannot establish their joint lobby probability. Its optimistic advantage reverses when those conditions are unavailable.']
    else:lines+=['','Preserved for comparison, not reaffirmed as optimal. It spreads SP across many modest skills and still relies on Cacao and See Ya Later. Final Push was overcredited in the prior Python model. Consider reserving uncertain purchases rather than treating full budget use as mandatory.']
lines+=['','## Purchase priorities supported by this experiment','','The six-item opening core (Winter ○, Firm ○, Front Savvy ○, Groundwork, Early Lead, Victoria) costs **522 SP**. Three guaranteed event/style greens satisfy Groundwork at the start; Groundwork itself still passes a WIT check (about 91% here). Outer Post is gate-dependent and should not substitute for a guaranteed third green. Buy greens before Groundwork in the review list so its setup is explicit.','','Turbo Sprint repeatedly beats white Sprinting Gear in isolated comparisons, but judge its **incremental** 160 SP against other purchases. Professor, gold proximity skills and ◎ greens have measured upgrade gains in `upgrade_ablation.csv`; those gains are context-dependent. Standard Distance and Moxie improve HP but did not improve solo finish times here. Focus is small in this isolated timing experiment; early position effects are not adequately valued by this solo test. Prideful King is incompatible with an always-leading assumption; no zero-value claim for every lobby is justified.','','Exact player discount validation still needs the current shop/hint levels. Data metadata supplies undiscounted bases and skill groups, not the trainee’s current discounted total. Never add a listed gold total on top of its white total.']
(ROOT/'cm21-study/recommended_shop_order.md').write_text('\n'.join(lines)+'\n')
lines=['# CM21 decision memo','','**The previous pseudo-simulation is reproducible, but its 2731-SP recommendation is not established as optimal.** Use the 522-SP opening core as the strongest common foundation for review. The remaining spend depends on positional-skill reliability. The three complete, budget-legal alternatives and their exact purchase order are in `recommended_shop_order.md`.','','## What was validated','','- Fetched research branch 96b870a and retained isolated `work`; upstream application and data are unchanged.','- Reproduced both original 24,000-race batches exactly and checked their 48,000-race aggregate.','- Ran original Global Umalator mechanics through an external TS harness: 38 single-skill rows, 9 upgrade comparisons, four Groundwork setups and complete budget packages. Trials per principal row: 1024, seed 2120226. Candidate screening: 128 trials on independent seed 7654321.','- Ran native application `runComparison` with solo and synthetic virtual pacers, 256 trials per row. These are pairwise margins, not nine-runner win rates.','- Exact deterministic baseline replay passed. Checked 15Hz vs 60Hz stepping; recorded full per-trial outputs and immutable source hashes.','','## Results and their practical limits','',f"Baseline (normal mood, unique Lv4, sampled side-contact condition): mean {v['baseline']['time']['mean']:.3f}s, range {v['baseline']['time']['min']:.3f}–{v['baseline']['time']['max']:.3f}s. Mean remaining HP {v['baseline']['hp']['mean']:.1%}, zero HP exhaustions in 1024. These are local-engine outputs, not observed race times. The unique activates in {v['baseline']['unique_activation']:.1%} of this sample because its proximity condition is modeled probabilistically; this is not an actual race trigger prediction.",'','| Package | SP | Sampled lead conditions: seconds saved | Proximity unavailable: seconds saved |','|---|---:|---:|---:|']
for name in ['opening_core','prior_balanced','prior_top_runner','candidate_1','candidate_2','conservative']:
    a=lookup[('sampled',name)];b=lookup[('no-proximity',name)];lines.append(f"| {name} | {a['sp']} | {float(a['seconds_saved']):.3f} | {float(b['seconds_saved']):.3f} |")
lines+=['','The conditional candidate improves on the prior balanced list under sampled lead conditions, but loses that advantage with proximity disabled. The lower-proximity-dependence alternative sacrifices optimistic mean gain for fewer unsupported opponent-interaction assumptions. No unconditional best purchase plan follows from these tests. Knapsack scores generate candidates; full-package tests check nonlinear interactions, including Tail Held High. This is a shortlist search, not an exhaustive optimization of every legal package.','','Victoria alone saves about 0.115s here at rank 1 with HP available, activating just past 800m. Groundwork alone never activates; three guaranteed greens enable it at about 91%, and greens+Groundwork save about 0.167s relative to native-only. The full 522-SP core saves about 0.310s under sampled lead assumptions. These findings justify prioritizing the opening setup and correctly timed acceleration for review.','','| Isolated upgrade in prior balanced context | Extra SP | Mean seconds saved |','|---|---:|---:|']
for r in up:lines.append(f"| {r['white']} → {r['gold']} | {r['incremental_sp']} | {float(r['seconds_saved']):.4f} |")
lines+=['','The gold Turbo result is a controlled upgrade, unlike the previous White Turbo + Focus multi-skill swap. Do not add single-skill gains to predict a complete package. Even statistically separated means remain conditional on these mechanics and settings.','','## Course and source caveats','','Local course 10701 has downhill 100–875m, uphill 875–975m, final straight at **800m**, final phase at 800m, and phase-3 boundary 1000m. The handoff’s 788m final straight is inconsistent with this local snapshot. No live client course data was available to adjudicate which geometry is current. Umalator downhill mode adds **0.2m/s target speed** for its -10000 slope, versus the prior Python model’s approximately 0.302. Neither is an instant movement-speed increase.','','The prior code incorrectly treats Final Push as speed instead of acceleration, ignores unique level scaling, changes green handling above 1200, simplifies spurt planning, overgrants Cacao and does not simulate teams. Details and source-level comparisons are in REPRO_AUDIT.md. The local I Wanna Win values are .42 speed/.24 acceleration; there is no fan-count input in the engine to independently check the 271,088-fan scaling.','','Course/skill data last changed October 1, 2026. No supplied live game database, practice replays or shop screenshot can independently establish live Global parity or current discounts. The supplied event conditions and prices remain explicit inputs.','','## Lobby conclusions','','Four original nine-runner compositions and three strength tiers were rerun, all synthetic. Their pseudo-win fractions must not be interpreted as observed or predicted Global CM probabilities. More fronts may reduce Victoria availability while enabling early interaction skills; solo-front/pace-heavy fields can favor different purchases. The local engine cannot calibrate that joint distribution from these tests.','','`opponent_sensitivity.csv` deliberately shows the same solo timing across attached rivals with position keeping disabled: adding an opponent object does not make rank/gap proxies faithful. `native_pairwise.json` additionally uses the application’s virtual-pacer workflow, including synthetic stronger Front and Pace pacers. Those results are measured within that workflow, not calibrated nine-agent CM outcomes. First-place statistics are among compared engine horses, not nine-runner lobby or team win rates.','','No empirical Global character/style frequency was collected. Historical JP percentages and community anecdotes in the handoff remain unverified background. The user’s teammates are not supplied; no 3v3v3 team-win recommendation is possible.','','## Uncertainty','','The CSV intervals quantify paired Monte Carlo variation only. Environment/trigger streams are aligned, but WIT-check consumption can change with activation order. Baseline 15Hz vs 60Hz times differ by about 0.022s on average; the tested package gains change by only a few milliseconds, recorded in timestep_sensitivity.csv. Structural uncertainty is larger: fixed order filters, sampled proximity, simplified pacers, disabled competition/dueling, unknown debuffs and current-client parity. A tiny mean advantage cannot settle purchases under these uncertainties.','','Before spending, verify current prices/upgrade totals and course implementation, then compare practice-room races with actual teammates and representative solo-front, contested-front and pace-heavy fields. Record actual Victoria/Top Runner/See Ya Later/Cacao trigger rates and Mad Dash stamina outcomes. This study supplies reproducible engine comparisons and bounded recommendations; it does not validate CM win percentages.']
lines+=['','## Native comparison cross-check','','Margins below are purchased build versus native-only baseline, in engine lengths (2.5m), 256 trials per cell. They are not seconds and not CM win probabilities. This separate path uses the unmodified application comparison function and its own RNG behavior.','','| Synthetic pacer setting | Prior balanced | Prior Top Runner | Conditional candidate | Lower-proximity package |','|---|---:|---:|---:|---:|']
pair=json.loads((R/'native_pairwise.json').read_text())
for mode in ['solo-comparison','virtual-front','virtual-pace','virtual-elite-front']:
    vals={x['package']:x['mean_engine_margin'] for x in pair if x['mode']==mode}
    lines.append('| '+mode+' | '+' | '.join(f"{vals[k]:.3f}" for k in ['prior_balanced','prior_top_runner','candidate_1','conservative'])+' |')
lines+=['','The prior Top Runner variant leads the balanced variant in the solo/front-pacer settings but trails it with the Pace pacer. This is evidence of sensitivity inside Umalator, not an estimate of how often each setting occurs in a nine-runner lobby.']
(ROOT/'cm21-study/DECISION_MEMO.md').write_text('\n'.join(lines)+'\n')
print('Validated all package budgets, skill-group exclusivity, exact replay, and unchanged upstream source. Wrote reports and source hashes.')
